{
  "description": "The creature is a quadrupedal hybrid shown in right profile against a plain off-white background, with the overall body, dense shaggy brown fur, head, legs and posture of a brown bear but with the glossy exoskeleton and horn of a rhinoceros beetle integrated into its back and forehead. It is walking to the right with one foreleg lifted, its bear-like body completely covered in thick brown fur except for a large, highly polished dark reddish-brown beetle shell that covers the shoulders and entire back from neck to rump, and a single large curved beetle horn projecting up from the forehead.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a brown bear head in right profile with dense brown fur, a lighter tan muzzle, a large black nose, small dark brown eyes, fine whiskers on the muzzle, and a closed mouth",
      "where": "at the front of the body, facing right"
    },
    {
      "part": "horns",
      "looks_like": "a single large, glossy dark reddish-brown rhinoceros beetle horn curving upward and backward, with two small pointed teeth on the inner curve and a shiny black circular base where it emerges from the fur on the forehead",
      "where": "centered on the forehead between the eyes and ears, projecting up and back"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, furry brown bear ears with dense fur",
      "where": "on top of the head behind the horn"
    },
    {
      "part": "legs",
      "looks_like": "four thick, muscular, shaggy brown bear legs covered in long brown fur, in a walking stride",
      "where": "two forelegs under the chest and shoulders, two hind legs under the hips and rump"
    },
    {
      "part": "feet",
      "looks_like": "four large brown bear paws with blunt dark claws and furry tops, the right fore paw lifted off the ground",
      "where": "at the ends of the four legs"
    },
    {
      "part": "tail",
      "looks_like": "a very short, stubby, furry brown bear tail",
      "where": "at the rear of the body above the hind legs"
    },
    {
      "part": "shell",
      "looks_like": "a large, highly glossy, dark reddish-brown beetle shell with light reflections, consisting of a smooth domed pronotum over the shoulders and a larger oval, longitudinally ridged elytra over the back with fine parallel lines and small dark speckles",
      "where": "covering the entire dorsal side from the back of the neck to the rump, sitting on top of the fur"
    },
    {
      "part": "plates",
      "looks_like": "a row of small, pointed, brown serrated plates with circular breathing holes along the lower margin where the shell meets the fur",
      "where": "along the bottom edge of both the pronotum and the elytra on the side of the body"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "rhinoceros beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
